140	function updateMine() {
141	  const e = Number(excavators.value);
142	  const t = Number(trucks.value);
143	
144	  const excavatorCapacity = e * 400;
145	  const truckCapacity = t * 90 * 3;
146	  const production = Math.min(excavatorCapacity, truckCapacity);
147	
148	  document.getElementById("excavatorCount").textContent = e;
149	  document.getElementById("truckCount").textContent = t;
150	  updateFleet(t);
151	
152	  document.querySelectorAll(".card strong")[0].textContent = e;
153	  document.querySelectorAll(".card strong")[1].textContent = t;
154	  document.querySelectorAll(".card strong")[2].textContent =
155	    production + " т/сағ";
156	
157	  document.getElementById("bottleneck").textContent =
158	    excavatorCapacity < truckCapacity
